begin;
select no_plan();
select has_table('public','customers','clientes existem');
select has_table('public','products','catálogo existe');
insert into auth.users(id) values ('20000000-0000-0000-0000-000000000001'), ('20000000-0000-0000-0000-000000000002'),('20000000-0000-0000-0000-000000000003');
insert into public.profiles values ('20000000-0000-0000-0000-000000000001','owner'),('20000000-0000-0000-0000-000000000002','driver'),('20000000-0000-0000-0000-000000000003','owner');
set local role anon;
select throws_ok('select * from public.customers','42501',null,'anônimo sem clientes');
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
set local role authenticated;
insert into public.products(id,name,eggs_per_tray,default_price_cents) values ('21000000-0000-0000-0000-000000000001','Bandeja teste 31',31,3300),('21000000-0000-0000-0000-000000000002','Bandeja teste 16',16,1700);
select is(public.save_customer('22000000-0000-0000-0000-000000000001',0,'{"name":"<img src=x onerror=alert(1)>","address":"Rua fictícia","phone":"81999990000","active":true,"weekday":4,"position":1}','[{"productId":"21000000-0000-0000-0000-000000000001","trays":6},{"productId":"21000000-0000-0000-0000-000000000002","trays":1}]','[{"productId":"21000000-0000-0000-0000-000000000001","priceCents":3000}]','23000000-0000-0000-0000-000000000001'),'{"id":"22000000-0000-0000-0000-000000000001","version":1}'::jsonb,'dona cadastra pedido e preço negociado');
select is((select count(*) from public.standing_order_items where customer_id='22000000-0000-0000-0000-000000000001'),2::bigint,'pedido tem múltiplos produtos');
select is((select price_cents from public.customer_prices where customer_id='22000000-0000-0000-0000-000000000001'),3000,'preço negociado em centavos');
select is((select sum(i.trays::bigint * coalesce(cp.price_cents,p.default_price_cents)) from public.standing_order_items i join public.products p on p.id=i.product_id left join public.customer_prices cp on cp.product_id=i.product_id and cp.customer_id=i.customer_id where i.customer_id='22000000-0000-0000-0000-000000000001'),19700::numeric,'negociado tem prioridade, demais usam padrão');
select is((select weekday from public.customers where id='22000000-0000-0000-0000-000000000001'),4,'dia da rota preservado');
select is((select position from public.customers where id='22000000-0000-0000-0000-000000000001'),1,'posição da rota preservada');
select is((select name from public.customers where id='22000000-0000-0000-0000-000000000001'),'<img src=x onerror=alert(1)>','texto armazenado como dado');
select is((public.save_customer('22000000-0000-0000-0000-000000000001',0,'{"name":"<img src=x onerror=alert(1)>","address":"Rua fictícia","phone":"81999990000","active":true,"weekday":4,"position":1}','[{"productId":"21000000-0000-0000-0000-000000000001","trays":6},{"productId":"21000000-0000-0000-0000-000000000002","trays":1}]','[{"productId":"21000000-0000-0000-0000-000000000001","priceCents":3000}]','23000000-0000-0000-0000-000000000001')->>'version')::int,1,'replay retorna mesma versão sem duplicar');
select throws_ok($$update public.customers set name='overwrite'$$,'42501',null,'escrita direta não ignora version');
select throws_ok($$insert into public.customer_prices values ('22000000-0000-0000-0000-000000000001','21000000-0000-0000-0000-000000000002',1)$$,'42501',null,'preço só muda atomicamente');
select throws_ok($$select public.save_customer('22000000-0000-0000-0000-000000000001',0,'{"name":"Sobrescrito","address":"Rua","active":true,"weekday":4,"position":1}','[]','[]',gen_random_uuid())$$,'PT409','VERSION_CONFLICT','versão antiga não sobrescreve');
select is((select trays from public.standing_order_items where customer_id='22000000-0000-0000-0000-000000000001' and product_id='21000000-0000-0000-0000-000000000001'),6,'conflito preserva itens');
select is((select price_cents from public.customer_prices where customer_id='22000000-0000-0000-0000-000000000001'),3000,'conflito preserva preço');
select throws_ok($$select public.save_customer('22000000-0000-0000-0000-000000000001',1,'{"name":"Inválido","address":"Rua","active":true,"weekday":4,"position":1}','[{"productId":"21000000-0000-0000-0000-000000000001","trays":1.5}]','[]',gen_random_uuid())$$,'22023','INVALID_INPUT','fração rejeitada sem truncar');
select throws_ok($$select public.save_customer('22000000-0000-0000-0000-000000000001',1,'{"name":"Inválido","address":"Rua","active":true,"weekday":4,"position":1}','[]','[{"productId":"21000000-0000-0000-0000-000000000001","priceCents":-1}]',gen_random_uuid())$$,'22023','INVALID_INPUT','preço negativo rejeitado');
select throws_ok($$select public.save_customer('22000000-0000-0000-0000-000000000001',1,'{"name":"Inválido","address":"Rua","active":true,"weekday":4,"position":1}','[{"productId":"21000000-0000-0000-0000-000000000001","trays":2147483648}]','[]',gen_random_uuid())$$,'22023','INVALID_INPUT','inteiro fora de faixa rejeitado');
select throws_ok($$select public.save_customer('22000000-0000-0000-0000-000000000001',1,'{"name":"Inválido","address":"Rua","active":true,"weekday":4,"position":1}','[{"productId":"99999999-0000-0000-0000-000000000001","trays":1}]','[]',gen_random_uuid())$$,'22023','INVALID_INPUT','produto inexistente não apaga pedido');
select is((select version from public.customers where id='22000000-0000-0000-0000-000000000001'),1,'erros revertem versão e cadastro');
select is((select count(*) from public.standing_order_items where customer_id='22000000-0000-0000-0000-000000000001'),2::bigint,'erro preserva todos itens');
select is((public.save_customer('22000000-0000-0000-0000-000000000001',1,'{"name":"Cliente fictício","address":"Rua nova","phone":null,"active":false,"weekday":4,"position":1}','[{"productId":"21000000-0000-0000-0000-000000000002","trays":2}]','[]',gen_random_uuid())->>'version')::int,2,'edição incrementa versão e inativa');
select is((select count(*) from public.customers where id='22000000-0000-0000-0000-000000000001' and not active),1::bigint,'inativar preserva cliente');
select is((select count(*) from public.standing_order_items where customer_id='22000000-0000-0000-0000-000000000001'),1::bigint,'edição substitui itens completos');
select is((select count(*) from public.customer_prices where customer_id='22000000-0000-0000-0000-000000000001'),0::bigint,'remover negociado restaura padrão');
select is(public.reconcile_customer_request('23000000-0000-0000-0000-000000000001'),'{"status":"saved","result":{"id":"22000000-0000-0000-0000-000000000001","version":1}}'::jsonb,'reconciliação retorna resultado confirmado');
select is(public.reconcile_customer_request('23000000-0000-0000-0000-000000000099'),'{"status":"closed"}'::jsonb,'reconciliação encerra tentativa ausente atomicamente');
select is(public.reconcile_customer_request('23000000-0000-0000-0000-000000000099'),'{"status":"closed"}'::jsonb,'encerramento idempotente');
select throws_ok($$select public.save_customer(gen_random_uuid(),0,'{"name":"Tardio","address":"Rua","active":true,"weekday":4,"position":1}','[]','[]','23000000-0000-0000-0000-000000000099')$$,'55000','REQUEST_CLOSED','envio tardio não cria cliente depois de encerrado');
select throws_ok($$select public.reconcile_customer_request(null)$$,'22023','INVALID_INPUT','reconciliação exige id');
reset role;
insert into private.request_events(request_id,actor_id,operation,payload_hash,result) values('23000000-0000-0000-0000-000000000098','20000000-0000-0000-0000-000000000001','another_operation','fixture','{}');
set local role authenticated;
select throws_ok($$select public.reconcile_customer_request('23000000-0000-0000-0000-000000000098')$$,'42501','FORBIDDEN','reconciliação não aceita outra operação');
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select is((select count(*) from public.customers),0::bigint,'motorista sem clientes diretos');
select is((select count(*) from public.products),0::bigint,'motorista sem catálogo com preço');
select is((select count(*) from public.customer_prices),0::bigint,'motorista sem preços');
select is((select count(*) from public.standing_order_items),0::bigint,'motorista sem itens com preço');
select throws_ok($$select public.reconcile_customer_request('23000000-0000-0000-0000-000000000001')$$,'42501','FORBIDDEN','motorista não reconcilia tentativa da dona');
select throws_ok($$select public.save_customer(gen_random_uuid(),0,'{"name":"x","address":"y","active":true,"weekday":4,"position":1}','[]','[]',gen_random_uuid())$$,'42501','FORBIDDEN','motorista não cadastra');
select throws_ok($$insert into public.products(name,eggs_per_tray,default_price_cents) values('x',30,1)$$,'42501',null,'motorista não cadastra catálogo');
reset role;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',true);
set local role authenticated;
select throws_ok($$select public.reconcile_customer_request('23000000-0000-0000-0000-000000000001')$$,'42501','FORBIDDEN','outra dona não reconcilia tentativa alheia');
select * from finish();
rollback;
